#pragma once
// Built-in anti-aliased ASCII fonts (generated by tools/gen_font.py).
namespace ui {

struct Glyph {
    int advance64;      ///< advance in 1/64 pixel
    int xoff, yoff;     ///< bitmap origin relative to the pen position on the baseline
    int w, h;           ///< bitmap size
    int offset;         ///< start of the 8-bit coverage bitmap in the face data
};

struct GlyphFace {
    int pixelSize, ascent, lineHeight;
    const Glyph* glyphs;   ///< characters 32 .. 126
    const unsigned char* data;
};

extern const GlyphFace gRegular11, gRegular13, gBold11, gBold13;

}  // namespace ui
